html:
{% set company_currency = doc.company_currency or frappe.db.get_value("Company", doc.company, "default_currency") %}

<style>
  table { width: 100%; border-collapse: collapse; margin-top: 10px; }
  th, td { border: 1px solid #000; padding: 6px; }
  th { background: #f0f0f0; }
  .text-right { text-align: right; }
</style>

<h2 style="text-align:center;">Sales Invoice</h2>

<p><b>Invoice No:</b> {{ doc.name }}</p>
<p><b>Date:</b> {{ frappe.format(doc.posting_date, {"fieldtype": "Date"}) }}</p>
<p><b>Customer ID:</b> {{ doc.customer }}</p>
<p><b>Customer Name:</b> {{ doc.customer_name }}</p>

<table>
  <thead>
    <tr>
      <th>Sr</th>
      <th>Product Details</th>
      <th class="text-right">Qty</th>
      <th class="text-right">Unit Rate</th>
      <th class="text-right">CGST</th>
      <th class="text-right">SGST</th>
      <th class="text-right">IGST</th>
      <th class="text-right">Taxable Amount</th>
    </tr>
  </thead>
  <tbody>
    {# --- collect invoice-level tax rates for fallback --- #}
    {% set inv_cgst_rate = 0 %}
    {% set inv_sgst_rate = 0 %}
    {% set inv_igst_rate = 0 %}
    {% for tx in (doc.taxes or []) %}
      {% if "CGST" in tx.account_head %}{% set inv_cgst_rate = tx.rate %}{% endif %}
      {% if "SGST" in tx.account_head %}{% set inv_sgst_rate = tx.rate %}{% endif %}
      {% if "IGST" in tx.account_head %}{% set inv_igst_rate = tx.rate %}{% endif %}
    {% endfor %}

    {# --- running totals --- #}
    {% set totals = {"qty": 0.0, "taxable": 0.0, "cgst": 0.0, "sgst": 0.0, "igst": 0.0} %}

    {% for row in doc.items %}
      {% set cgst_rate = 0 %}
      {% set sgst_rate = 0 %}
      {% set igst_rate = 0 %}
      {% set cgst_amt = 0 %}
      {% set sgst_amt = 0 %}
      {% set igst_amt = 0 %}

      {# 1) Try per-item item_tax_rate (JSON string) #}
      {% set tax_map = frappe.parse_json(row.item_tax_rate) if row.item_tax_rate else {} %}
      {% if tax_map %}
        {% for tax_head, rate in tax_map.items() %}
          {% if "CGST" in tax_head %}{% set cgst_rate = rate %}{% endif %}
          {% if "SGST" in tax_head %}{% set sgst_rate = rate %}{% endif %}
          {% if "IGST" in tax_head %}{% set igst_rate = rate %}{% endif %}
        {% endfor %}
      {% endif %}

      {# 2) If still zero, try Item Tax Template on the row #}
      {% if (cgst_rate == 0 and sgst_rate == 0 and igst_rate == 0) and row.item_tax_template %}
        {% set itt = frappe.get_doc("Item Tax Template", row.item_tax_template) %}
        {% for t in (itt.taxes or []) %}
          {% if "CGST" in t.tax_type %}{% set cgst_rate = t.tax_rate %}{% endif %}
          {% if "SGST" in t.tax_type %}{% set sgst_rate = t.tax_rate %}{% endif %}
          {% if "IGST" in t.tax_type %}{% set igst_rate = t.tax_rate %}{% endif %}
        {% endfor %}
      {% endif %}

      {# 3) If still zero, fall back to invoice-level tax rates #}
      {% if cgst_rate == 0 and sgst_rate == 0 and igst_rate == 0 %}
        {% set cgst_rate = inv_cgst_rate %}
        {% set sgst_rate = inv_sgst_rate %}
        {% set igst_rate = inv_igst_rate %}
      {% endif %}

      {# compute amounts #}
      {% set cgst_amt = (row.amount * cgst_rate / 100.0) %}
      {% set sgst_amt = (row.amount * sgst_rate / 100.0) %}
      {% set igst_amt = (row.amount * igst_rate / 100.0) %}

      {# update totals #}
      {% set _ = totals.update({
        "qty": totals["qty"] + (row.qty or 0),
        "taxable": totals["taxable"] + (row.amount or 0),
        "cgst": totals["cgst"] + cgst_amt,
        "sgst": totals["sgst"] + sgst_amt,
        "igst": totals["igst"] + igst_amt
      }) %}

      <tr>
        <td>{{ row.idx }}</td>
        <td>
          {% if row.item_code != row.item_name %}<b>{{ row.item_code }}</b><br>{% endif %}
          {{ row.item_name }}
        </td>
        <td class="text-right">{{ row.qty }}</td>
        <td class="text-right">{{ row.get_formatted("rate", doc) }}</td>

        <td class="text-right">
          {{ frappe.format(cgst_amt, {"fieldtype": "Currency", "options": company_currency}) }}<br>
          <small>{{ cgst_rate|round(2) }}%</small>
        </td>
        <td class="text-right">
          {{ frappe.format(sgst_amt, {"fieldtype": "Currency", "options": company_currency}) }}<br>
          <small>{{ sgst_rate|round(2) }}%</small>
        </td>
        <td class="text-right">
          {{ frappe.format(igst_amt, {"fieldtype": "Currency", "options": company_currency}) }}<br>
          <small>{{ igst_rate|round(2) }}%</small>
        </td>
        <td class="text-right">{{ row.get_formatted("amount", doc) }}</td>
      </tr>
    {% endfor %}

    {# totals row #}
    <tr>
      <td colspan="2" class="text-right"><b>Totals</b></td>
      <td class="text-right"><b>{{ totals["qty"] }}</b></td>
      <td></td>
      <td class="text-right"><b>{{ frappe.format(totals["cgst"], {"fieldtype": "Currency", "options": company_currency}) }}</b></td>
      <td class="text-right"><b>{{ frappe.format(totals["sgst"], {"fieldtype": "Currency", "options": company_currency}) }}</b></td>
      <td class="text-right"><b>{{ frappe.format(totals["igst"], {"fieldtype": "Currency", "options": company_currency}) }}</b></td>
      <td class="text-right"><b>{{ frappe.format(totals["taxable"], {"fieldtype": "Currency", "options": company_currency}) }}</b></td>
    </tr>
  </tbody>
</table>

<h3 style="text-align:right;">Net Total: {{ frappe.format(doc.net_total, {"fieldtype": "Currency", "options": company_currency}) }}</h3>
<h3 style="text-align:right;">Grand Total: {{ frappe.format(doc.grand_total, {"fieldtype": "Currency", "options": company_currency}) }}</h3>
